<script>
    function SafeGetValue(obj, path, defaultValue = "N/A") {
        let keys = Array.isArray(path) ? path : path.split('.');
        let current = obj;
        for (let i = 0; i < keys.length; i++) {
            if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(keys[i])) return defaultValue;
            current = current[keys[i]];
        }
        if (current === undefined || current === null) return defaultValue;

        let actualValue = Array.isArray(current) ? (current.length > 0 ? current[0] : defaultValue) : current;
        if (typeof actualValue === 'boolean') return actualValue;

        let displayValue = String(actualValue);

        if (typeof displayValue === 'string' && displayValue.includes('->')) {
            try {
                const parts = displayValue.split('->');
                if (parts.length > 1) {
                    const secondPart = parts[1];
                    const finalValue = secondPart.split('(')[0].trim();
                    displayValue = finalValue;
                }
            } catch (e) {}
        }
        return displayValue;
    }

    function toggleSection(element) {
        const content = element.nextElementSibling;
        const arrow = element.querySelector('span:last-child');
        if (!content || !arrow) return;
